from datetime import datetime

def parse_date(s):
    if '-' in s:
        return datetime.strptime(s, '%Y-%m-%d').date()
    elif '/' in s:
        return datetime.strptime(s, '%d/%m/%Y').date()
    else:
        raise ValueError("Input date string must be in 'YYYY-MM-DD' or 'DD/MM/YYYY' format.")
```

